-- Name: Toilet Dashboard - SL Coverage - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

SELECT DATE(DATE_ADD('MINUTE', 330, __time)) AS doi, -- bus_operator, event_src, -- app_version, COUNT(DISTINCT CASE WHEN event_group = 'sl_screen_load' THEN mri_session_id END) AS sl_load_sessions, COUNT( DISTINCT CASE WHEN event_group = 'sl_click_info' AND event_name = 'ToiletShown' THEN mri_session_id END ) AS toilet_shown_sessions, COUNT( DISTINCT CASE WHEN event_group = 'sl_click_info' AND event_name = 'safetyDetailsLoaded' THEN mri_session_id END ) AS safety_Details_Loaded_sessions, COUNT( DISTINCT CASE WHEN event_group = 'sl_click_info' AND event_name = 'DMSloaded' THEN mri_session_id END ) AS DMS_loaded_sessions, COUNT( DISTINCT CASE WHEN event_group = 'sl_click_info' AND event_name = 'emergencyShown' THEN mri_session_id END ) AS side_Emergency_Shown_sessions, COUNT( DISTINCT CASE WHEN event_group = 'sl_click_info' AND event_name = 'rearEmergencyShown' THEN mri_session_id END ) AS rear_Emergency_Shown_sessions, COUNT( DISTINCT CASE WHEN event_group = 'sl_click_info' AND event_name = 'roofEmergencyShown' THEN mri_session_id END ) AS roof_Emergency_Shown_sessions FROM user_interaction.ui_ux_events AS uue WHERE __time >= CAST('2026-07-11 18:30:00' AS TIMESTAMP) AND __time < CAST('2026-07-15 18:30:00' AS TIMESTAMP) AND ((upper(event_src) = 'ANDROID' AND app_code >= 821000) OR (upper(event_src) = 'IOS' AND app_code >= 862200)) AND header_bu = 'BUS' AND header_country = 'IND' GROUP BY 1, 2 -- , 3 -- HAVING COUNT(DISTINCT CASE WHEN event_group = 'sl_screen_load' THEN mri_session_id END) > 0 ORDER BY 1, 2
